import { createContext, useContext, useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import { useToast } from './ToastContext';

// Simple UUID generator to avoid dependency issues
const generateUUID = () => {
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
        var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
};

const CrewContext = createContext();

export const useCrew = () => useContext(CrewContext);

export const CrewProvider = ({ children }) => {
    const { user } = useAuth();
    const { showToast } = useToast();
    const [crews, setCrews] = useState([]);
    const [currentCrew, setCurrentCrew] = useState(null);
    const [loading, setLoading] = useState(true);

    // Load from LocalStorage on mount
    useEffect(() => {
        const storedCrews = localStorage.getItem('lspa_crews');
        if (storedCrews) {
            try {
                let parsed = JSON.parse(storedCrews);
                const cleanCrews = parsed.filter(c => c.id !== 'crew-1' && c.id !== 'crew-2');
                if (cleanCrews.length !== parsed.length) {
                    localStorage.setItem('lspa_crews', JSON.stringify(cleanCrews));
                }
                
                // Recalculate points on load using DEEP SCANNER
                const crewsWithPoints = cleanCrews.map(crew => ({
                    ...crew,
                    crewPoints: calculateCrewXP(crew.members)
                }));
                
                setCrews(crewsWithPoints);
            } catch (e) {
                console.error("Error parsing crews:", e);
                setCrews([]);
            }
        } else {
            setCrews([]);
        }
        setLoading(false);
    }, []);

    // Sync currentCrew when user or crews change
    useEffect(() => {
        if (!loading && user) {
            const userCrew = crews.find(c => c.members.some(m => m.userId === user.id));
            setCurrentCrew(userCrew || null);
        } else if (!user) {
            setCurrentCrew(null);
        }
    }, [crews, user, loading]);

    // Persist to LS whenever crews change
    useEffect(() => {
        if (!loading) {
            localStorage.setItem('lspa_crews', JSON.stringify(crews));
        }
    }, [crews, loading]);

    // --- XP CALCULATOR ---
    
    // Función auxiliar para sumar niveles (Nivel Total)
    const calculateCrewXP = (members = []) => {
        if (!Array.isArray(members)) return 0;
        
        return members.reduce((acc, member) => {
            // Priority: member.level -> member.xp -> 1
            const level = parseInt(member.level || member.xp || 1, 10);
            return acc + (isNaN(level) ? 1 : level);
        }, 0);
    };

    const calculateCrewPoints = calculateCrewXP;

    // --- ACTIONS ---

    const createCrew = (crewData) => {
        if (!user) {
            showToast('error', 'Debes iniciar sesión');
            return;
        }
        
        const initialLevel = 1; // Defined constant
        
        // AUDIT FIX: Verify exact location of level in AuthContext (user.stats.level)
        const newCrew = {
            id: generateUUID(),
            ...crewData,
            privacy: crewData.privacy || 'public',
            crewPoints: initialLevel, 
            members: [{ 
                userId: user.id, 
                username: user.username,
                avatar: user.avatar,
                level: user.stats?.level || initialLevel,
                role: 'owner', 
                joinedAt: Date.now() 
            }],
            pendingRequests: [],
            chat: [],
            memberLimit: 50,
            createdAt: Date.now()
        };

        setCrews(prev => [...prev, newCrew]);
        showToast('success', `¡Crew "${newCrew.name}" fundada con éxito!`);
        return newCrew;
    };

    const joinCrew = (crewId) => {
        if (!user) return;
        if (currentCrew) {
            showToast('error', 'Ya perteneces a una Crew, debes salir antes.');
            return;
        }

        setCrews(prev => prev.map(crew => {
            if (crew.id === crewId) {
                if (crew.privacy === 'closed') {
                    showToast('warning', 'Esta crew es privada y no acepta solicitudes.');
                    return crew;
                }

                if (crew.members.length >= 50) {
                    showToast('error', 'La crew está llena (Máx 50).');
                    return crew;
                }

                // INVITE ONLY: create a pending request
                if (crew.privacy === 'invite_only') {
                    const alreadyRequested = (crew.pendingRequests || []).some(r => r.userId === user.id);
                    if (alreadyRequested) {
                        showToast('warning', 'Ya tienes una solicitud pendiente en esta crew.');
                        return crew;
                    }
                    const newRequest = {
                        userId: user.id,
                        username: user.username,
                        avatar: user.avatar,
                        level: parseInt(user.stats?.level || user.level || 1, 10),
                        requestedAt: Date.now()
                    };
                    showToast('success', `Solicitud enviada a ${crew.name}. Espera aprobación.`);
                    return {
                        ...crew,
                        pendingRequests: [...(crew.pendingRequests || []), newRequest]
                    };
                }

                // PUBLIC: join directly
                const userLevel = parseInt(user.stats?.level || user.level || 1, 10);
                const newMembers = [...crew.members, { 
                    userId: user.id, 
                    username: user.username,
                    avatar: user.avatar,
                    level: userLevel,
                    role: 'noob', 
                    joinedAt: Date.now() 
                }];
                
                showToast('success', `Te has unido a ${crew.name}`);
                return {
                    ...crew,
                    members: newMembers,
                    crewPoints: calculateCrewPoints(newMembers)
                };
            }
            return crew;
        }));
    };

    // Handle join request (approve/reject) for invite_only crews
    const handleJoinRequest = (crewId, requestUserId, approved) => {
        setCrews(prev => prev.map(crew => {
            if (crew.id !== crewId) return crew;
            
            const request = (crew.pendingRequests || []).find(r => r.userId === requestUserId);
            if (!request) return crew;

            // Remove from pending
            const updatedRequests = crew.pendingRequests.filter(r => r.userId !== requestUserId);

            if (approved) {
                if (crew.members.length >= 50) {
                    showToast('error', 'La crew está llena.');
                    return { ...crew, pendingRequests: updatedRequests };
                }
                const newMembers = [...crew.members, {
                    userId: request.userId,
                    username: request.username,
                    avatar: request.avatar,
                    level: request.level,
                    role: 'noob',
                    joinedAt: Date.now()
                }];
                showToast('success', `${request.username} ha sido aceptado en la crew.`);
                return {
                    ...crew,
                    members: newMembers,
                    pendingRequests: updatedRequests,
                    crewPoints: calculateCrewXP(newMembers)
                };
            } else {
                showToast('info', `Solicitud de ${request.username} rechazada.`);
                return { ...crew, pendingRequests: updatedRequests };
            }
        }));
    };

    // Check if user has pending request for a crew
    const hasPendingRequest = (crewId) => {
        if (!user) return false;
        const crew = crews.find(c => c.id === crewId);
        return (crew?.pendingRequests || []).some(r => r.userId === user.id);
    };

    const deleteCrew = (crewId) => {
        if (!user) return;
        setCrews(prev => prev.filter(c => c.id !== crewId));
        if (currentCrew?.id === crewId) {
            setCurrentCrew(null);
            showToast('info', 'La Crew ha sido disuelta.');
        }
    };

    const leaveCrew = () => {
        if (!user || !currentCrew) return;

        if (currentCrew.members.length === 1 && currentCrew.members[0].userId === user.id) {
            deleteCrew(currentCrew.id);
            return;
        }

        setCrews(prev => prev.map(crew => {
            if (crew.id === currentCrew.id) {
                const updatedMembers = crew.members.filter(m => m.userId !== user.id);
                return {
                    ...crew,
                    members: updatedMembers,
                    crewPoints: calculateCrewPoints(updatedMembers)
                };
            }
            return crew;
        }));
        setCurrentCrew(null);
        showToast('info', 'Has abandonado la crew.');
    };

    const updateCrewInfo = (crewId, updates) => {
        setCrews(prev => prev.map(crew => {
            if (crew.id === crewId) {
                return { ...crew, ...updates };
            }
            return crew;
        }));
        showToast('success', 'Información actualizada');
    };

    const manageMember = (crewId, targetUserId, action, payload) => {
        const rankOrder = ['noob', 'veteran', 'staff', 'co-owner', 'owner'];
        
        setCrews(prev => prev.map(crew => {
            if (crew.id !== crewId) return crew;
            
            let updatedMembers = [...crew.members];
            const targetIndex = updatedMembers.findIndex(m => m.userId === targetUserId);
            if (targetIndex === -1) return crew;
            
            const targetUser = updatedMembers[targetIndex];

            if (action === 'kick') {
                updatedMembers = updatedMembers.filter(m => m.userId !== targetUserId);
                showToast('success', `Has expulsado a ${targetUser.username}`);
            } else if (action === 'promote' || action === 'demote') {
                 // Explicitly using params, avoiding arguments object
                const currentRankIdx = rankOrder.indexOf(targetUser.role);
                if (action === 'promote' && currentRankIdx < rankOrder.length - 2) { 
                     updatedMembers[targetIndex].role = rankOrder[currentRankIdx + 1];
                     showToast('success', `${targetUser.username} promovido a ${rankOrder[currentRankIdx + 1].toUpperCase()}`);
                } else if (action === 'demote' && currentRankIdx > 0) {
                     updatedMembers[targetIndex].role = rankOrder[currentRankIdx - 1];
                     showToast('info', `${targetUser.username} degradado a ${rankOrder[currentRankIdx - 1].toUpperCase()}`);
                }
            } else if (action === 'setRole') {
                // STRICT SECURITY CHECK
                const myUser = crew.members.find(m => m.userId === user.id);
                const myRole = myUser ? myUser.role : 'noob';
                
                const roles = { 'owner': 4, 'co-owner': 3, 'staff': 2, 'veteran': 1, 'noob': 0 };
                const myRank = roles[myRole];
                const newRole = payload; 
                const newRank = roles[newRole];
                const targetRank = roles[targetUser.role];

                // Rule 1
                if (targetRank >= myRank) {
                    showToast('error', 'No tienes rango suficiente.');
                    return crew;
                }

                // Rule 2
                if (newRank >= myRank) {
                    showToast('error', 'No puedes otorgar un rango igual o superior al tuyo.');
                    return crew;
                }

                updatedMembers[targetIndex].role = newRole;
                showToast('success', `Rol actualizado a ${newRole.toUpperCase()}`);
            }

            // Recalculate points using robust function
            return { 
                ...crew, 
                members: updatedMembers,
                crewPoints: calculateCrewXP(updatedMembers)
            };
        }));
    };

    const sendCrewMessage = (type, content) => {
        if (!user || !currentCrew) return;

        const newMessage = {
            id: generateUUID(),
            senderId: user.id,
            senderName: user.username, 
            senderAvatar: user.avatar,
            role: currentCrew.members.find(m => m.userId === user.id)?.role || 'noob',
            type, // text, image, vehicle
            content,
            timestamp: Date.now()
        };

        setCrews(prev => prev.map(crew => {
            if (crew.id === currentCrew.id) {
                return {
                    ...crew,
                    chat: [...crew.chat, newMessage]
                };
            }
            return crew;
        }));
    };
    
    const canManage = (myRole, targetRole) => {
        const roles = { 'owner': 4, 'co-owner': 3, 'staff': 2, 'veteran': 1, 'noob': 0 };
        return roles[myRole] > roles[targetRole];
    };

    return (
        <CrewContext.Provider value={{
            crews,
            currentCrew,
            loading,
            createCrew,
            joinCrew,
            leaveCrew,
            deleteCrew,
            updateCrewInfo,
            manageMember,
            sendCrewMessage,
            canManage,
            handleJoinRequest,
            hasPendingRequest
        }}>
            {children}
        </CrewContext.Provider>
    );
};

import { createContext, useContext } from 'react';
import { useAuth } from './AuthContext';

const GamificationContext = createContext();

export const useGamification = () => useContext(GamificationContext);

// Shared Key - Must match AuthContext
const DB_KEY = 'lspa_users_db_v2';

export const GamificationProvider = ({ children }) => {
    const { user, updateUser } = useAuth();

    // --- MATH & LOGIC ---

    // Level = floor(0.1 * sqrt(XP)) + 1
    // Example: 100 XP -> sqrt(100)=10 -> 1.0 -> Level 2
    // Example: 10000 XP -> sqrt(10000)=100 -> 10.0 -> Level 11
    const calculateLevel = (xp) => {
        if (xp < 0) return 1;
        return Math.floor(0.1 * Math.sqrt(xp)) + 1;
    };

    // Calculate XP needed for NEXT level
    // Formula Inversion: Level = 0.1 * sqrt(XP) + 1  => (Level - 1) * 10 = sqrt(XP) => XP = ((Level - 1) * 10)^2
    // Next Level XP = ((CurrentLevel) * 10)^2
    // Example: Current Level 1. Next is 2. XP needed for 2 = ((2-1)*10)^2 = 100.
    // Example: Current Level 2. Next is 3. XP needed for 3 = ((3-1)*10)^2 = 400.
    const getXpForNextLevel = (currentLevel) => {
        return Math.pow(currentLevel * 10, 2);
    };

    // --- ACTIONS ---

    const addXp = (min, max) => {
        if (!user) return null;

        const amount = Math.floor(Math.random() * (max - min + 1)) + min;
        
        const currentStats = user.stats || { xp: 0, level: 1, gamesPlayed: 0 };
        const newXp = (currentStats.xp || 0) + amount;
        const newLevel = calculateLevel(newXp);
        const gamesPlayed = (currentStats.gamesPlayed || 0) + 1;

        // Check level up
        const leveledUp = newLevel > (currentStats.level || 1);

        if (leveledUp) {
            const audio = new Audio('https://www.myinstants.com/media/sounds/gta-sa-mission-passed.mp3');
            audio.volume = 0.5;
            audio.play().catch(() => {});
        }

        // Persist via Auth
        updateUser({
            stats: {
                ...currentStats,
                xp: newXp,
                level: newLevel,
                gamesPlayed
            }
        });

        return { amount, leveledUp, newLevel };
    };

    // New: Update High Score for a specific game
    const updateHighScore = (gameKey, score) => {
        if (!user) return false;

        const currentHighScores = user.highScores || {};
        const currentRecord = currentHighScores[gameKey] || 0;

        if (score > currentRecord) {
            // New Record!
            updateUser({
                highScores: {
                    ...currentHighScores,
                    [gameKey]: score
                }
            });
            return true; // Use this to show "NEW RECORD" UI
        }
        return false;
    };

    const getLeaderboard = () => {
        const dbStr = localStorage.getItem(DB_KEY);
        if (!dbStr) return [];
        const users = JSON.parse(dbStr);

        return users
            .map(u => ({
                username: u.username,
                avatar: u.avatar,
                level: u.stats?.level || 1,
                xp: u.stats?.xp || 0
            }))
            .sort((a, b) => b.xp - a.xp)
            .slice(0, 10);
    };

    // Helper to get progress % for UI
    const getLevelProgress = () => {
        if (!user || !user.stats) return 0;
        const { xp, level } = user.stats;
        // Note: Logic allows infinite levels.
        
        // Let's simplify progress bar:
        // XP needed for current level base:
        const base = Math.pow((level - 1) * 10, 2);
        const target = Math.pow(level * 10, 2);
        
        const totalRange = target - base;
        const progress = xp - base;
        
        const percent = Math.min(100, Math.max(0, (progress / totalRange) * 100));
        return percent;
    };
    
    // Helpers
    const currentLevel = user?.stats?.level || 1;
    const currentXp = user?.stats?.xp || 0;
    const nextLevelXp = getXpForNextLevel(currentLevel);

    const value = {
        addXp,
        calculateLevel,
        getLeaderboard,
        getLevelProgress,
        level: currentLevel,
        xp: currentXp,
        nextLevelXp,
        updateHighScore
    };

    return (
        <GamificationContext.Provider value={value}>
            {children}
        </GamificationContext.Provider>
    );
};

