import { useState, useEffect } from 'react';

import { useAuth } from '../../context/AuthContext';
import { useNavigate } from 'react-router-dom';
import { useNoticias } from '../../context/NoticiasContext';
import CustomDropdown from '../../components/custom-dropdown/CustomDropdown';
import './AdminPanel.css';

const EMPTY_NOTICIA = { titulo: '', descripcion: '', categoria: 'GTA Online', autor: '', fecha: '', imagen: '', tags: '' };

const AdminPanel = () => {
    const { user, getAllUsers, deleteUser, adminUpdateUser, ADMIN_ID, isAdmin } = useAuth();
    const { noticias, addNoticia, updateNoticia, deleteNoticia } = useNoticias();
    const navigate = useNavigate();

    // --- TAB ---
    const [activeTab, setActiveTab] = useState('usuarios');

    // --- USERS ---
    const [users, setUsers] = useState([]);
    const [editingUser, setEditingUser] = useState(null);
    const [deleteTarget, setDeleteTarget] = useState(null);
    const [formData, setFormData] = useState({});

    // --- NOTICIAS ---
    const [searchNoticias, setSearchNoticias] = useState('');
    const [noticiaModal, setNoticiaModal] = useState(null); // null | 'new' | noticia object (edit)
    const [noticiaForm, setNoticiaForm] = useState(EMPTY_NOTICIA);
    const [deleteNoticia_, setDeleteNoticia_] = useState(null);

    // --- SHARED ---
    const [notification, setNotification] = useState(null);

    useEffect(() => {
        if (!isAdmin) { navigate('/'); }
        else { setUsers(getAllUsers()); }
    }, [isAdmin, navigate, getAllUsers]);

    // Tab switch: if url has #noticias, auto-switch
    useEffect(() => {
        if (window.location.hash === '#noticias') setActiveTab('noticias');
    }, []);

    const showNotification = (msg) => {
        setNotification(msg);
        setTimeout(() => setNotification(null), 3000);
    };

    const refreshUsers = () => setUsers(getAllUsers());

    // ─── USERS CRUD ──────────────────────────────────────────────
    const canManage = (currentUser, targetUser) => {
        if (!currentUser) return false;
        if (currentUser.role === 'owner' || currentUser.id === ADMIN_ID) return true;
        if (currentUser.role === 'admin') {
            if (targetUser.role === 'owner' || targetUser.id === ADMIN_ID) return false;
            return true;
        }
        return false;
    };

    const handleDeleteClick = (u) => setDeleteTarget(u);
    const confirmDelete = () => {
        if (deleteTarget) {
            deleteUser(deleteTarget.id);
            setDeleteTarget(null);
            refreshUsers();
            showNotification(`Usuario ${deleteTarget.username} eliminado.`);
        }
    };
    const handleEditClick = (u) => {
        setEditingUser(u);
        setFormData({ username: u.username, bio: u.bio || '', role: u.role || 'user', level: u.stats?.level || 1, xp: u.stats?.xp || 0, password: u.password, avatar: u.avatar || '' });
    };
    const handleSave = () => {
        if (!editingUser) return;
        adminUpdateUser(editingUser.id, { username: formData.username, bio: formData.bio, role: formData.role, password: formData.password, avatar: formData.avatar, stats: { ...editingUser.stats, level: parseInt(formData.level), xp: parseInt(formData.xp) } });
        setEditingUser(null);
        refreshUsers();
        showNotification('Usuario actualizado correctamente.');
    };
    const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

    // ─── NOTICIAS CRUD ────────────────────────────────────────────
    const filteredNoticias = noticias.filter(n => {
        const term = searchNoticias.toLowerCase();
        return !term || n.titulo?.toLowerCase().includes(term) || n.autor?.toLowerCase().includes(term) || n.categoria?.toLowerCase().includes(term);
    });

    const openNewNoticia = () => {
        setNoticiaForm({ ...EMPTY_NOTICIA, fecha: new Date().toISOString().split('T')[0] });
        setNoticiaModal('new');
    };
    const openEditNoticia = (n) => {
        setNoticiaForm({ ...n, tags: Array.isArray(n.tags) ? n.tags.join(', ') : n.tags || '' });
        setNoticiaModal(n);
    };
    const handleNoticiaChange = (e) => setNoticiaForm(prev => ({ ...prev, [e.target.name]: e.target.value }));
    const handleSaveNoticia = () => {
        if (!noticiaForm.titulo.trim() || !noticiaForm.descripcion.trim()) {
            showNotification('⚠️ Título y descripción son obligatorios.');
            return;
        }
        if (noticiaModal === 'new') {
            addNoticia(noticiaForm);
            showNotification('✅ Noticia creada correctamente.');
        } else {
            updateNoticia(noticiaModal.id, noticiaForm);
            showNotification('✅ Noticia actualizada correctamente.');
        }
        setNoticiaModal(null);
    };
    const confirmDeleteNoticia = () => {
        if (deleteNoticia_) {
            deleteNoticia(deleteNoticia_.id);
            setDeleteNoticia_(null);
            showNotification(`🗑️ Noticia eliminada.`);
        }
    };

    return (
        <div className="admin-container">
            {notification && <div className="admin-notification">{notification}</div>}

            <div className="admin-header">
                <h1>Panel de Administración 🛡️</h1>
                <p>Bienvenido, {user?.role === 'owner' ? 'Owner' : 'Admin'}. Gestiona usuarios y noticias del foro.</p>
            </div>

            {/* TABS */}
            <div className="admin-tabs">
                <button className={`admin-tab ${activeTab === 'usuarios' ? 'active' : ''}`} onClick={() => setActiveTab('usuarios')}>
                    👥 Usuarios
                </button>
                <button id="tab-noticias" className={`admin-tab ${activeTab === 'noticias' ? 'active' : ''}`} onClick={() => setActiveTab('noticias')}>
                    📰 Noticias del Foro
                </button>
            </div>

            {/* ─── TAB: USUARIOS ─── */}
            {activeTab === 'usuarios' && (<>
                <div className="admin-stats">
                    <div className="stat-card"><h3>Usuarios Totales</h3><p>{users.length}</p></div>
                    <div className="stat-card"><h3>Owners / Admins</h3><p>{users.filter(u => u.role === 'admin' || u.role === 'owner' || u.id === ADMIN_ID).length}</p></div>
                </div>
                <div className="users-table-container">
                    <table className="admin-table">
                        <thead><tr><th>Usuario</th><th>ID</th><th>Nivel / XP</th><th>Rol</th><th>Acciones</th></tr></thead>
                        <tbody>
                            {users.map(u => (
                                <tr key={u.id}>
                                    <td><div className="user-cell"><img src={u.avatar} alt="avatar" className="user-avatar-mini" /><div><strong>{u.username}</strong><div style={{fontSize:'0.75rem',color:'#888'}}>{u.email}</div></div></div></td>
                                    <td style={{fontFamily:'monospace',fontSize:'0.8rem',color:'#666'}}>{u.id}</td>
                                    <td>LVL {u.stats?.level || 1}<br/><small style={{color:'#888'}}>{u.stats?.xp || 0} XP</small></td>
                                    <td><span className={`role-badge ${u.role === 'owner' || u.id === ADMIN_ID ? 'owner' : (u.role === 'admin' ? 'admin' : 'user')}`}>{u.id === ADMIN_ID ? 'OWNER' : (u.role ? u.role.toUpperCase() : 'USER')}</span></td>
                                    <td>
                                        {canManage(user, u) ? (<>
                                            <button className="action-btn btn-edit" onClick={() => handleEditClick(u)}>EDITAR</button>
                                            {u.id !== user.id && <button className="action-btn btn-delete" onClick={() => handleDeleteClick(u)}>ELIMINAR</button>}
                                        </>) : <span style={{fontSize:'0.8rem',color:'#555',fontStyle:'italic'}}>Protegido</span>}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </>)}

            {/* ─── TAB: NOTICIAS ─── */}
            {activeTab === 'noticias' && (
                <div className="noticias-admin-section">
                    <div className="noticias-admin-header">
                        <div className="noticias-search-wrap">
                            <span>🔍</span>
                            <input
                                type="text"
                                placeholder="Buscar por título, autor o categoría..."
                                value={searchNoticias}
                                onChange={e => setSearchNoticias(e.target.value)}
                            />
                        </div>
                        <button className="btn-new-noticia" onClick={openNewNoticia}>➕ Nueva Noticia</button>
                    </div>

                    <p className="noticias-count">{filteredNoticias.length} noticias {searchNoticias && `para "${searchNoticias}"`}</p>

                    <div className="noticias-admin-table-wrap">
                        <table className="admin-table noticias-table">
                            <thead>
                                <tr>
                                    <th>Título</th>
                                    <th>Categoría</th>
                                    <th>Autor</th>
                                    <th>Fecha</th>
                                    <th>Likes</th>
                                    <th>Acciones</th>
                                </tr>
                            </thead>
                            <tbody>
                                {filteredNoticias.map(n => (
                                    <tr key={n.id}>
                                        <td className="noticia-titulo-cell" title={n.titulo}>{n.titulo}</td>
                                        <td><span className="noticia-cat-badge">{n.categoria}</span></td>
                                        <td>{n.autor}</td>
                                        <td style={{whiteSpace:'nowrap'}}>{n.fecha}</td>
                                        <td>❤️ {n.likes || 0}</td>
                                        <td>
                                            <button className="action-btn btn-edit" onClick={() => openEditNoticia(n)}>✏️ Editar</button>
                                            <button className="action-btn btn-delete" onClick={() => setDeleteNoticia_(n)}>🗑️ Eliminar</button>
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            )}

            {/* ─── MODAL: EDITAR/CREAR NOTICIA ─── */}
            {noticiaModal !== null && (
                <div className="editor-modal">
                    <div className="editor-content" style={{maxWidth: '640px'}}>
                        <div className="editor-header">
                            <h2>{noticiaModal === 'new' ? '➕ Nueva Noticia' : '✏️ Editar Noticia'}</h2>
                            <button className="close-btn" onClick={() => setNoticiaModal(null)}>×</button>
                        </div>
                        <div className="editor-body">
                            <div className="form-group">
                                <label>Título *</label>
                                <input type="text" name="titulo" value={noticiaForm.titulo} onChange={handleNoticiaChange} placeholder="Título de la noticia..." />
                            </div>
                            <div className="form-group">
                                <label>Descripción *</label>
                                <textarea name="descripcion" value={noticiaForm.descripcion} onChange={handleNoticiaChange} rows="4" placeholder="Contenido de la noticia..." />
                            </div>
                            <div className="form-row">
                                <div className="form-group">
                                    <label>Categoría</label>
                                    <CustomDropdown
                                        options={[
                                            { value: 'GTA Online',    label: '🎮 GTA Online',    color: '#00F0FF' },
                                            { value: 'Coches Reales', label: '🏎️ Coches Reales', color: '#FFD700' },
                                            { value: 'Tuning',        label: '🔧 Tuning',        color: '#FF4500' },
                                            { value: 'Carreras',      label: '🏁 Carreras',      color: '#00FF64' },
                                            { value: 'Novedades',     label: '📰 Novedades',     color: '#BE00FF' },
                                        ]}
                                        value={noticiaForm.categoria}
                                        onChange={(val) => setNoticiaForm(prev => ({ ...prev, categoria: val }))}
                                        accentColor="var(--primary-color)"
                                        fullWidth
                                    />
                                </div>
                                <div className="form-group">
                                    <label>Autor</label>
                                    <input type="text" name="autor" value={noticiaForm.autor} onChange={handleNoticiaChange} placeholder="Nombre del autor..." />
                                </div>
                            </div>
                            <div className="form-row">
                                <div className="form-group">
                                    <label>Fecha</label>
                                    <input type="date" name="fecha" value={noticiaForm.fecha} onChange={handleNoticiaChange} />
                                </div>
                                <div className="form-group">
                                    <label>Imagen (URL)</label>
                                    <input type="text" name="imagen" value={noticiaForm.imagen} onChange={handleNoticiaChange} placeholder="https://..." />
                                </div>
                            </div>
                            <div className="form-group">
                                <label>Tags (separados por coma)</label>
                                <input type="text" name="tags" value={noticiaForm.tags} onChange={handleNoticiaChange} placeholder="ej: gta, tuning, carreras" />
                            </div>
                        </div>
                        <div className="editor-footer">
                            <button className="btn-cancel" onClick={() => setNoticiaModal(null)}>Cancelar</button>
                            <button className="btn-save" onClick={handleSaveNoticia}>
                                {noticiaModal === 'new' ? '✅ Publicar' : '✅ Guardar Cambios'}
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* ─── MODAL: CONFIRMAR BORRAR NOTICIA ─── */}
            {deleteNoticia_ && (
                <div className="editor-modal">
                    <div className="editor-content" style={{maxWidth:'400px',textAlign:'center'}}>
                        <div className="editor-header" style={{justifyContent:'center',borderBottom:'none'}}>
                            <h2 style={{color:'#ff003c'}}>⚠️ ELIMINAR NOTICIA</h2>
                        </div>
                        <div className="editor-body">
                            <p>¿Eliminar <strong>"{deleteNoticia_.titulo}"</strong>?</p>
                            <p style={{fontSize:'0.9rem',color:'#888'}}>Esta acción no se puede deshacer.</p>
                        </div>
                        <div className="editor-footer" style={{justifyContent:'center'}}>
                            <button className="btn-cancel" onClick={() => setDeleteNoticia_(null)}>Cancelar</button>
                            <button className="btn-save" style={{background:'#ff003c',color:'white'}} onClick={confirmDeleteNoticia}>ELIMINAR</button>
                        </div>
                    </div>
                </div>
            )}

            {/* ─── MODAL: EDITAR USUARIO ─── */}
            {editingUser && (
                <div className="editor-modal">
                    <div className="editor-content">
                        <div className="editor-header">
                            <h2>Editando: {editingUser.username}</h2>
                            <button className="close-btn" onClick={() => setEditingUser(null)}>×</button>
                        </div>
                        <div className="editor-body">
                            <div className="form-row">
                                <div className="form-group"><label>Nombre de Usuario</label><input type="text" name="username" value={formData.username} onChange={handleChange} /></div>
                                <div className="form-group">
                                    <label>Rol</label>
                                    <CustomDropdown options={[{ value:'user',label:'👤 Usuario',color:'#fff'},{value:'admin',label:'🛡️ Admin',color:'var(--secondary-color)'},...((user.role==='owner'||user.id===ADMIN_ID)?[{value:'owner',label:'👑 Owner',color:'var(--primary-color)'}]:[])]} value={formData.role} onChange={(val)=>setFormData({...formData,role:val})} accentColor="var(--secondary-color)" fullWidth />
                                </div>
                            </div>
                            <div className="form-group"><label>URL del Avatar</label><input type="text" name="avatar" value={formData.avatar} onChange={handleChange} placeholder="https://..." /></div>
                            <div className="form-group"><label>Contraseña</label><input type="text" name="password" value={formData.password} onChange={handleChange} /></div>
                            <div className="form-group"><label>Biografía</label><textarea name="bio" value={formData.bio} onChange={handleChange} rows="3"/></div>
                            <div className="form-row">
                                <div className="form-group"><label>Nivel</label><input type="number" name="level" value={formData.level} onChange={handleChange} /></div>
                                <div className="form-group"><label>XP Total</label><input type="number" name="xp" value={formData.xp} onChange={handleChange} /></div>
                            </div>
                        </div>
                        <div className="editor-footer">
                            <button className="btn-cancel" onClick={() => setEditingUser(null)}>Cancelar</button>
                            <button className="btn-save" onClick={handleSave}>Guardar Cambios</button>
                        </div>
                    </div>
                </div>
            )}

            {/* ─── MODAL: CONFIRMAR BORRAR USUARIO ─── */}
            {deleteTarget && (
                <div className="editor-modal">
                    <div className="editor-content" style={{maxWidth:'400px',textAlign:'center'}}>
                        <div className="editor-header" style={{justifyContent:'center',borderBottom:'none'}}>
                            <h2 style={{color:'#ff003c'}}>⚠️ ELIMINAR USUARIO</h2>
                        </div>
                        <div className="editor-body">
                            <p>¿Estás seguro de que quieres eliminar a <strong>{deleteTarget.username}</strong>?</p>
                            <p style={{fontSize:'0.9rem',color:'#888'}}>Esta acción no se puede deshacer.</p>
                        </div>
                        <div className="editor-footer" style={{justifyContent:'center'}}>
                            <button className="btn-cancel" onClick={() => setDeleteTarget(null)}>Cancelar</button>
                            <button className="btn-save" style={{background:'#ff003c',color:'white'}} onClick={confirmDelete}>ELIMINAR</button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AdminPanel;

import { useState, useEffect } from 'react';
// Custom Modal inside Admin for consistent styling
const AdminConfirmModal = ({ isOpen, title, message, onConfirm, onCancel }) => {
    if (!isOpen) return null;
    return (
        <div className="modal-overlay">
            <div className="admin-modal-content">
                <h3 className="admin-modal-title">{title}</h3>
                <p className="admin-modal-message">{message}</p>
                <div className="modal-actions">
                    <button onClick={onCancel} className="admin-btn-cancel">CANCELAR</button>
                    <button onClick={onConfirm} className="admin-btn-confirm">CONFIRMAR</button>
                </div>
            </div>
        </div>
    );
};

// --- DANGER MODAL (RED THEME) ---
const DangerModal = ({ isOpen, title, message, onConfirm, onCancel }) => {
    if (!isOpen) return null;
    return (
        <div className="modal-overlay" style={{backdropFilter: 'blur(5px)'}}>
            <div className="modal-content danger-modal">
                <h3>⚠️ {title}</h3>
                <p>{message}</p>
                <div className="modal-actions">
                    <button onClick={onCancel} className="btn-modal-cancel">CANCELAR</button>
                    <button onClick={onConfirm} className="btn-modal-danger">ELIMINAR DEFINITIVAMENTE</button>
                </div>
            </div>
        </div>
    );
};

const CrewAdmin = () => {
    const { currentCrew, updateCrewInfo, manageMember, deleteCrew, handleJoinRequest } = useCrew();
    const { user } = useAuth();
    const navigate = useNavigate();
    
    // Local state
    const [formData, setFormData] = useState({
        name: '', description: '', tag: '', logoUrl: '', privacy: 'public'
    });

    const [modalConfig, setModalConfig] = useState({ open: false, title: '', message: '', action: null });
    const [dangerModal, setDangerModal] = useState({ open: false, title: '', message: '', action: null });

    useEffect(() => {
        if (!currentCrew) {
            navigate('/crews');
            return;
        }
        
        const myRole = currentCrew.members.find(m => m.userId === user.id)?.role;
        const allowedRoles = ['owner', 'co-owner', 'staff'];
        if (!allowedRoles.includes(myRole)) {
            navigate('/crews');
        }

        setFormData({
            name: currentCrew.name,
            description: currentCrew.description,
            tag: currentCrew.tag,
            logoUrl: currentCrew.logoUrl || '',
            privacy: currentCrew.privacy || 'public'
        });

    }, [currentCrew, user, navigate]);

    if (!currentCrew) return null;

    const handleSave = () => {
        updateCrewInfo(currentCrew.id, formData);
        // Toast is already handled in context, but we can add one here if context doesn't return
        // Actually context shows 'Success', so we don't need duplicate.
    };

    const openConfirm = (title, message, action) => {
        setModalConfig({ open: true, title, message, action });
    };

    const openDanger = (title, message, action) => {
        setDangerModal({ open: true, title, message, action });
    };

    const handleConfirm = () => {
        if (modalConfig.action) modalConfig.action();
        setModalConfig({ ...modalConfig, open: false });
    };

    const handleDangerConfirm = () => {
        if (dangerModal.action) dangerModal.action();
        setDangerModal({ ...dangerModal, open: false });
    };

    const myMemberRole = currentCrew.members.find(m => m.userId === user.id)?.role;
    
    // EMERGENCY DISBAND LOGIC (CASCADING AUTHORITY):
    // 1. Owner always can.
    // 2. Staff can IF no Owner AND no Co-Owner.
    // 3. Veteran can IF no Owner, no Co-Owner AND no Staff.
    
    const hasOwnerOrCo = currentCrew.members.some(m => m.role === 'owner' || m.role === 'co-owner');
    const hasStaff = currentCrew.members.some(m => m.role === 'staff');

    let canDisband = false;

    if (myMemberRole === 'owner') {
        canDisband = true;
    } else if (myMemberRole === 'staff') {
        canDisband = !hasOwnerOrCo; // Only if abandoned by leaders
    } else if (myMemberRole === 'veteran') {
        canDisband = !hasOwnerOrCo && !hasStaff; // Only if abandoned by everyone above
    }

    return (
        <div className="crew-admin-container">
            <header className="admin-header">
                <button className="back-btn" onClick={() => navigate('/crews')}>‹ VOLVER AL DASHBOARD</button>
                <h1>⚙️ PANEL DE LIDERAZGO: <span className="neon-text">{currentCrew.name}</span></h1>
            </header>

            <div className="admin-grid">
                {/* SECTION 1: GENERAL SETTINGS */}
                <section className="admin-card settings-card">
                    <h2>✏️ Ajustes Generales</h2>
                    <div className="input-group">
                        <label>Nombre de la Crew</label>
                        <input 
                            type="text" 
                            value={formData.name} 
                            onChange={e => setFormData({...formData, name: e.target.value})}
                        />
                    </div>
                    {/* ... (rest of inputs same as before, simplified for brevity in replacement if needed, but keeping full) ... */}
                    <div className="input-group">
                        <label>TAG (3-4 letras)</label>
                        <input 
                            type="text" 
                            maxLength={4}
                            value={formData.tag} 
                            onChange={e => setFormData({...formData, tag: e.target.value})}
                        />
                    </div>
                    <div className="input-group">
                        <label>Logo URL</label>
                        <input 
                            type="url" 
                            value={formData.logoUrl} 
                            onChange={e => setFormData({...formData, logoUrl: e.target.value})}
                        />
                    </div>
                     <div className="input-group">
                        <label>Privacidad</label>
                        <CustomDropdown
                            options={[
                                { value: 'public', label: '🔓 Pública', color: 'var(--success)' },
                                { value: 'invite_only', label: '✉️ Solo Invitación', color: 'var(--primary-color)' },
                                { value: 'closed', label: '🔒 Cerrada', color: '#ff4444' },
                            ]}
                            value={formData.privacy}
                            onChange={(val) => setFormData({...formData, privacy: val})}
                            accentColor="var(--primary-color)"
                            fullWidth
                        />
                    </div>
                    <div className="input-group">
                        <label>Lema / Descripción</label>
                        <textarea 
                            rows={4}
                            value={formData.description} 
                            onChange={e => setFormData({...formData, description: e.target.value})}
                        />
                    </div>
                    <button className="save-changes-btn glow-effect" onClick={handleSave}>
                        GUARDAR CAMBIOS
                    </button>
                </section>

                {/* SECTION 2: MEMBER MANAGEMENT */}
                <section className="admin-card members-card">
                    <h2>👮 Gestión de Personal ({currentCrew.members.length})</h2>
                    <div className="admin-members-list">
                        <table>
                            <thead>
                                <tr>
                                    <th>Usuario</th>
                                    <th>Rango</th>
                                    <th>Acciones</th>
                                </tr>
                            </thead>
                            <tbody>
                                {currentCrew.members
                                    .sort((a, b) => (a.role === 'owner' ? -1 : b.role === 'owner' ? 1 : 0)) // Owner first
                                    .map(member => (
                                    <tr key={member.userId}>
                                        <td className="user-cell">
                                            <img src={member.avatar || 'https://placehold.co/40'} alt="avatar" className="mini-avatar"/>
                                            <span>{member.username || member.userId.slice(0,5)}</span>
                                        </td>
                                        <td>
                                            <span className={`badge badge-${member.role}`}>{member.role.toUpperCase()}</span>
                                        </td>
                                        <td className="actions-cell">
                                            {member.userId !== user.id ? (
                                                (() => {
                                                    const roles = { 'owner': 4, 'co-owner': 3, 'staff': 2, 'veteran': 1, 'noob': 0 };
                                                    const myRank = roles[myMemberRole || 'noob'];
                                                    const targetRank = roles[member.role];
                                                    
                                                    // Logic: Can only manage if my rank > target rank
                                                    const canEdit = myRank > targetRank;

                                                    // Logic: Can only assign roles STRICTLY LOWER than mine
                                                    const allRoles = ['co-owner', 'staff', 'veteran', 'noob'];
                                                    const assignableRoles = allRoles.filter(r => roles[r] < myRank);

                                                    return (
                                                        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                                            <CustomDropdown
                                                                options={[
                                                                    // Show current role if outside assignable range
                                                                    ...(!assignableRoles.includes(member.role) ? [{ value: member.role, label: member.role.toUpperCase(), color: 'var(--text-muted)' }] : []),
                                                                    ...assignableRoles.map(role => ({ value: role, label: role.toUpperCase(), color: role === 'co-owner' ? 'var(--primary-color)' : role === 'staff' ? 'var(--secondary-color)' : '#fff' }))
                                                                ]}
                                                                value={member.role}
                                                                onChange={(val) => manageMember(currentCrew.id, member.userId, 'setRole', val)}
                                                                accentColor="var(--secondary-color)"
                                                                disabled={!canEdit}
                                                            />

                                                            {canEdit && (
                                                                <button title="Expulsar" className="action-btn kick" onClick={() => 
                                                                    openConfirm('Expulsar Miembro', `¿Seguro que deseas expulsar a ${member.username}?`, () => manageMember(currentCrew.id, member.userId, 'kick'))
                                                                }>✕</button>
                                                            )}
                                                        </div>
                                                    );
                                                })()
                                            ) : (
                                                <span style={{color: '#888', fontSize: '0.8rem'}}>Tú</span>
                                            )}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    {/* PENDING REQUESTS (invite_only) */}
                    {(currentCrew.pendingRequests || []).length > 0 && (
                        <div className="pending-requests-section">
                            <h3 className="pending-title">📩 Solicitudes Pendientes ({currentCrew.pendingRequests.length})</h3>
                            <div className="pending-list">
                                {currentCrew.pendingRequests.map(req => (
                                    <div key={req.userId} className="pending-item">
                                        <div className="pending-user-info">
                                            <img src={req.avatar || 'https://placehold.co/40'} alt="avatar" className="mini-avatar" />
                                            <div>
                                                <span className="pending-username">{req.username}</span>
                                                <span className="pending-level">Nivel {req.level}</span>
                                            </div>
                                        </div>
                                        <div className="pending-actions">
                                            <button 
                                                className="approve-btn" 
                                                onClick={() => handleJoinRequest(currentCrew.id, req.userId, true)}
                                                title="Aceptar"
                                            >✓</button>
                                            <button 
                                                className="reject-btn" 
                                                onClick={() => handleJoinRequest(currentCrew.id, req.userId, false)}
                                                title="Rechazar"
                                            >✕</button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        </div>
                    )}
                </section>

                {/* SECTION 3: DANGER ZONE */}
                {canDisband && (
                    <section className="admin-card danger-card">
                        <h2>☠️ ZONA DE PELIGRO</h2>
                        <p>Estas acciones son irreversibles. Ten cuidado.</p>
                        <button className="disband-btn" onClick={() => 
                            openDanger('ELIMINAR CREW', '¿ESTÁS SEGURO? Esta acción es DEFINITIVA e IRREVERSIBLE. Se borrará todo.', () => {
                                deleteCrew(currentCrew.id);
                                navigate('/crews');
                            })
                        }>
                            DISOLVER CREW
                        </button>
                    </section>
                )}
            </div>

            <AdminConfirmModal 
                isOpen={modalConfig.open} 
                title={modalConfig.title} 
                message={modalConfig.message} 
                onConfirm={handleConfirm} 
                onCancel={() => setModalConfig({...modalConfig, open: false})}
            />

            <DangerModal 
                isOpen={dangerModal.open} 
                title={dangerModal.title} 
                message={dangerModal.message} 
                onConfirm={handleDangerConfirm} 
                onCancel={() => setDangerModal({ ...dangerModal, open: false })}
            />
        </div>
    );
};

export default CrewAdmin;

import { useState, useMemo } from 'react';

import { useCrew } from '../../context/CrewContext';
import { useToast } from '../../context/ToastContext';
import { useNavigate } from 'react-router-dom';
import CustomDropdown from '../../components/custom-dropdown/CustomDropdown';
import './CrewExplorer.css'; 

const CrewExplorer = () => {
    const { crews, joinCrew, createCrew, currentCrew, loading, hasPendingRequest } = useCrew();
    const { showToast } = useToast();
    const navigate = useNavigate(); // Navigation hook
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCrew, setSelectedCrew] = useState(null);

    const [sortBy, setSortBy] = useState('level_desc'); // Default: Highest Level First

    // Create Crew State
    const [showCreateModal, setShowCreateModal] = useState(false);
    const [createFormData, setCreateFormData] = useState({
        name: '', tag: '', logoUrl: '', description: '', privacy: 'public'
    });

    // Calculate Points Helper (Hoisted)
    const getCrewPoints = (membersArray) => {
        if (!membersArray || !Array.isArray(membersArray)) return 0;
        return membersArray.reduce((total, member) => {
            const level = parseInt(member.level || 1, 10);
            return total + (isNaN(level) ? 1 : level);
        }, 0);
    };

    // Filter Logic
    const filteredCrews = useMemo(() => crews.filter(c => 
        c.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
        c.tag.toLowerCase().includes(searchTerm.toLowerCase())
    ), [crews, searchTerm]);

    // Sort Logic
    const sortedCrews = useMemo(() => [...filteredCrews].sort((a, b) => {
        // Use pre-calculated points from Context if available, else fallback
        const pointsA = a.crewPoints ?? getCrewPoints(a.members);
        const pointsB = b.crewPoints ?? getCrewPoints(b.members);
        const membersA = a.members.length;
        const membersB = b.members.length;

        switch (sortBy) {
            case 'level_desc': return pointsB - pointsA;
            case 'level_asc': return pointsA - pointsB;
            case 'members_desc': return membersB - membersA;
            case 'members_asc': return membersA - membersB;
            default: return 0;
        }
    }), [filteredCrews, sortBy]);

    // Back Button Logic
    const handleBack = () => {
        if (currentCrew) {
            navigate('/crews');
        } else {
            navigate('/profile'); // or /home
        }
    };

    // Handle Create Crew
    const handleCreateCrew = (e) => {
        e.preventDefault();
        if (!createFormData.name || !createFormData.tag) {
            showToast('error', 'Nombre y Tag son obligatorios');
            return;
        }
        createCrew(createFormData);
        setShowCreateModal(false);
        navigate('/crews'); // Redirect to dashboard to see new crew
    };

    return (
        <div className="crew-explorer-container">
            {/* --- HEADER --- */}
            <div className="explorer-header" style={{ position: 'relative' }}>
                <button 
                    onClick={handleBack}
                    style={{
                        position: 'absolute',
                        top: '20px',
                        left: '20px',
                        background: 'transparent',
                        border: '1px solid #444',
                        color: '#ccc',
                        padding: '8px 15px',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '5px'
                    }}
                >
                    ⬅ Volver
                </button>

                <h1>🔭 Explorador de Crews</h1>
                <p style={{ color: '#aaa', marginBottom: '20px' }}>Busca, compite y domina Los Santos.</p>
                
                <div style={{ display: 'flex', gap: '10px', justifyContent: 'center', flexWrap: 'wrap' }}>
                    <input 
                        type="text" 
                        placeholder="Buscar por Nombre o TAG..." 
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        className="search-input"
                    />
                    
                    {/* CREATE CREW BUTTON - Restored */}
                    {!currentCrew && (
                        <button 
                            onClick={() => setShowCreateModal(true)}
                            className="neon-pulse"
                            style={{
                                background: 'linear-gradient(45deg, #FFD700, #FFA500)',
                                border: 'none',
                                color: 'black',
                                fontWeight: 'bold',
                                padding: '0 20px',
                                borderRadius: '4px',
                                cursor: 'pointer',
                                height: '50px',
                                fontSize: '1rem',
                                boxShadow: '0 0 15px rgba(255, 215, 0, 0.4)'
                            }}
                        >
                            + CREAR CREW
                        </button>
                    )}
                </div>

                {/* SORTING DROPDOWN */}
                <div style={{ 
                    marginTop: '20px', 
                    display: 'flex', 
                    justifyContent: 'center', 
                    alignItems: 'center', 
                    maxWidth: 'fit-content',
                    margin: '20px auto'
                }}>
                    <CustomDropdown
                        label="Ordenar:"
                        options={[
                            { value: 'level_desc', label: '🏆 Nivel Total (Mayor a Menor)', color: 'var(--primary-color)' },
                            { value: 'level_asc', label: '🐣 Nivel Total (Menor a Mayor)', color: 'var(--text-muted)' },
                            { value: 'members_desc', label: '👥 Miembros (Más poblada)', color: 'var(--secondary-color)' },
                            { value: 'members_asc', label: '👤 Miembros (Menos poblada)', color: 'var(--text-muted)' },
                        ]}
                        value={sortBy}
                        onChange={setSortBy}
                        accentColor="var(--primary-color)"
                    />
                </div>
            </div>

            {/* --- GRID --- */}
            <div className="crews-grid-unified">
                {sortedCrews.map(crew => {
                    const isMyCrew = currentCrew?.id === crew.id;
                    const hasCrew = !!currentCrew;
                    const isFull = crew.members.length >= (crew.memberLimit || 50); // UPDATED LIMIT
                    const points = getCrewPoints(crew.members);

                    return (
                        <div 
                            key={crew.id} 
                            className="crew-card-unified" 
                            onClick={() => setSelectedCrew(crew)}
                            style={isMyCrew ? { border: '1px solid var(--primary-color)', background: 'rgba(255, 215, 0, 0.05)' } : {}}
                        >
                            {/* LOGO - STRICTLY SIZED (NUCLEAR OPTION) */}
                            <img 
                                src={crew.logoUrl || 'https://placehold.co/150'} 
                                alt={crew.name}
                                style={{
                                    width: '80px',
                                    height: '80px',
                                    minWidth: '80px',
                                    objectFit: 'cover',
                                    borderRadius: '50%',
                                    flexShrink: 0,
                                    backgroundColor: '#222',
                                    border: '2px solid #333'
                                }}
                                onError={(e) => e.target.src = 'https://placehold.co/150'}
                            />

                            {/* INFO */}
                            <div className="crew-card-info">
                                <span className="crew-tag">[{crew.tag}]</span>
                                <h3 className="crew-name">{crew.name}</h3>
                                <div className="crew-meta">
                                    <span>👥 {crew.members.length} / {crew.memberLimit || 50}</span>
                                    <span>🏆 {points} NIVEL TOTAL</span>
                                </div>
                            </div>

                            {/* ACTION BUTTON (Logic Awareness) */}
                            <div>
                                {isMyCrew ? (
                                    <span style={{ 
                                        color: 'var(--primary-color)', 
                                        fontWeight: 'bold', 
                                        fontSize: '0.8rem', 
                                        border: '1px solid var(--primary-color)', 
                                        padding: '4px 8px', 
                                        borderRadius: '4px' 
                                    }}>TU CREW</span>
                                ) : hasCrew ? (
                                    <button className="card-action-btn btn-member">VER DETALLES</button>
                                ) : isFull ? (
                                    <button className="card-action-btn btn-full">LLENO</button>
                                ) : hasPendingRequest(crew.id) ? (
                                    <button className="card-action-btn btn-member" disabled>⏳ PENDIENTE</button>
                                ) : crew.privacy === 'invite_only' ? (
                                    <button className="card-action-btn btn-invite">✉️ SOLICITAR</button>
                                ) : crew.privacy === 'closed' ? (
                                    <button className="card-action-btn btn-full" disabled>🔒 CERRADA</button>
                                ) : (
                                    <button className="card-action-btn btn-join">UNIRSE</button>
                                )}
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* --- SPECTATOR MODAL --- */}
            {selectedCrew && (
                <div className="explorer-modal-overlay" onClick={() => setSelectedCrew(null)}>
                    {(() => {
                        const isFull = selectedCrew.members.length >= (selectedCrew.memberLimit || 50);
                        return (
                        <div className="explorer-modal-content" onClick={e => e.stopPropagation()}>
                            <img 
                                src={selectedCrew.logoUrl || 'https://placehold.co/150'} 
                                alt="Hero"
                                className="modal-hero-img"
                            />
                        <h2 style={{ fontSize: '1.8rem', margin: '10px 0' }}>{selectedCrew.name}</h2>
                        <span className="crew-tag" style={{ fontSize: '1.2rem' }}>[{selectedCrew.tag}]</span>
                        
                        <p style={{ margin: '20px 0', color: '#ccc', fontStyle: 'italic' }}>
                            "{selectedCrew.description || 'Sin descripción disponible.'}"
                        </p>

                        <div style={{ display: 'flex', justifyContent: 'center', gap: '30px', margin: '20px 0' }}>
                            <div>
                                <h4 style={{ color: '#888', textTransform: 'uppercase', fontSize: '0.8rem' }}>Miembros</h4>
                                <span style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>{selectedCrew.members.length}</span>
                            </div>
                            <div>
                                <h4 style={{ color: '#888', textTransform: 'uppercase', fontSize: '0.8rem' }}>Puntos</h4>
                                <span style={{ fontSize: '1.5rem', fontWeight: 'bold' }}>{getCrewPoints(selectedCrew.members)}</span>
                            </div>
                        </div>

                        {/* Modal Action Logic */}
                        {currentCrew?.id === selectedCrew.id ? (
                            <button 
                                className="card-action-btn" 
                                style={{ width: '100%', padding: '15px', background: 'var(--primary-color)', color: 'black' }}
                                onClick={() => navigate('/crews')}
                            >
                                IR A MI DASHBOARD
                            </button>
                        ) : !currentCrew && selectedCrew.members.length < (selectedCrew.memberLimit || 50) ? (
                            hasPendingRequest(selectedCrew.id) ? (
                                <button 
                                    className="card-action-btn btn-member" 
                                    style={{ width: '100%', padding: '15px', fontSize: '1.1rem' }}
                                    disabled
                                >
                                    ⏳ SOLICITUD PENDIENTE
                                </button>
                            ) : (
                                <button 
                                    className="card-action-btn btn-join" 
                                    style={{ width: '100%', padding: '15px', fontSize: '1.1rem' }}
                                    onClick={() => {
                                        joinCrew(selectedCrew.id);
                                        if (selectedCrew.privacy !== 'invite_only') {
                                            setSelectedCrew(null);
                                            navigate('/crews');
                                        } else {
                                            setSelectedCrew(null);
                                        }
                                    }}
                                >
                                    {selectedCrew.privacy === 'invite_only' ? '✉️ ENVIAR SOLICITUD' : 'UNIRSE AHORA'}
                                </button>
                            )
                        ) : (
                             <button 
                                className="card-action-btn btn-member" 
                                style={{ width: '100%', padding: '15px', fontSize: '1.1rem' }}
                                disabled
                            >
                                {isFull ? 'CREW LLENA' : 'YA TIENES CREW'}
                            </button>
                        )}
                        
                        <button 
                            onClick={() => setSelectedCrew(null)}
                            style={{ 
                                background: 'transparent', border: 'none', color: '#666', 
                                marginTop: '15px', cursor: 'pointer', textDecoration: 'underline' 
                            }}
                        >
                            Cerrar Vista Previa
                        </button>
                    </div>
                    );
                })()} 
                </div>
            )}

            {/* --- CREATE CREW MODAL --- */}
            {showCreateModal && (
                <div className="explorer-modal-overlay">
                    <div className="explorer-modal-content" style={{ maxWidth: '500px' }}>
                        <h2 style={{ marginBottom: '20px', color: '#FFD700' }}>👑 Fundar Nueva Crew</h2>
                        
                        <form onSubmit={handleCreateCrew} style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
                            <div>
                                <label style={{ display: 'block', marginBottom: '5px', color: '#aaa' }}>Nombre de la Crew</label>
                                <input 
                                    type="text" 
                                    className="search-input" 
                                    style={{ width: '100%' }}
                                    value={createFormData.name}
                                    onChange={e => setCreateFormData({...createFormData, name: e.target.value})}
                                    required 
                                />
                            </div>
                            <div>
                                <label style={{ display: 'block', marginBottom: '5px', color: '#aaa' }}>TAG (Máx 4 letras)</label>
                                <input 
                                    type="text" 
                                    className="search-input" 
                                    style={{ width: '100%', textTransform: 'uppercase' }}
                                    maxLength={4}
                                    value={createFormData.tag}
                                    onChange={e => setCreateFormData({...createFormData, tag: e.target.value.toUpperCase()})}
                                    required 
                                />
                            </div>
                            <div>
                                <label style={{ display: 'block', marginBottom: '5px', color: '#aaa' }}>URL del Logo</label>
                                <input 
                                    type="url" 
                                    className="search-input" 
                                    style={{ width: '100%' }}
                                    placeholder="https://..."
                                    value={createFormData.logoUrl}
                                    onChange={e => setCreateFormData({...createFormData, logoUrl: e.target.value})}
                                />
                            </div>
                            <div>
                                <label style={{ display: 'block', marginBottom: '5px', color: '#aaa' }}>Lema / Descripción</label>
                                <textarea 
                                    className="search-input"
                                    style={{ width: '100%', minHeight: '80px', fontFamily: 'inherit' }}
                                    value={createFormData.description}
                                    onChange={e => setCreateFormData({...createFormData, description: e.target.value})}
                                />
                            </div>

                            <div style={{ display: 'flex', gap: '10px', marginTop: '10px' }}>
                                <button 
                                    type="button" 
                                    onClick={() => setShowCreateModal(false)}
                                    style={{
                                        flex: 1, padding: '12px', background: '#333', color: 'white',
                                        border: 'none', borderRadius: '4px', cursor: 'pointer'
                                    }}
                                >
                                    Cancelar
                                </button>
                                <button 
                                    type="submit" 
                                    disabled={loading} // Basic check, ideally local state
                                    style={{
                                        flex: 1, padding: '12px', background: loading ? '#555' : '#FFD700', color: loading ? '#ccc' : 'black',
                                        border: 'none', borderRadius: '4px', cursor: loading ? 'not-allowed' : 'pointer', fontWeight: 'bold'
                                    }}
                                >
                                    {loading ? 'CREANDO...' : 'CREAR CREW'}
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default CrewExplorer;

